package com.photoalbum.config;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.HttpMethod;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.core.userdetails.User;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.provisioning.InMemoryUserDetailsManager;
import org.springframework.security.web.SecurityFilterChain;

/**
 * Security configuration.
 *
 * The photo gallery is publicly readable, but the state-changing endpoints
 * (photo upload and delete) require authentication so anonymous callers can no
 * longer create or destroy data (CWE-862 / CWE-306). The admin credentials are
 * supplied via environment variables (app.admin.username / app.admin.password),
 * never hard-coded.
 */
@Configuration
public class SecurityConfig {

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }

    @Bean
    public InMemoryUserDetailsManager userDetailsService(
            PasswordEncoder passwordEncoder,
            @Value("${app.admin.username:admin}") String adminUsername,
            @Value("${app.admin.password}") String adminPassword) {
        UserDetails admin = User.withUsername(adminUsername)
                .password(passwordEncoder.encode(adminPassword))
                .roles("ADMIN")
                .build();
        return new InMemoryUserDetailsManager(admin);
    }

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
            // Stateless HTTP Basic auth: credentials are sent per request, so a
            // session-based CSRF token is not applicable. CSRF is disabled to
            // keep this security fix minimal without breaking the JSON upload API.
            .csrf().disable()
            .sessionManagement().sessionCreationPolicy(SessionCreationPolicy.STATELESS)
            .and()
            .authorizeRequests()
                .antMatchers(HttpMethod.GET, "/health").permitAll()
                // Default deny for state-changing operations (CWE-862 / CWE-306).
                .antMatchers(HttpMethod.POST, "/upload", "/detail/*/delete").authenticated()
                // Public, read-only photo gallery.
                .anyRequest().permitAll()
            .and()
            .httpBasic();
        return http.build();
    }
}

package com.photoalbum.controller;

import java.sql.Connection;
import java.sql.SQLException;
import java.util.Collections;
import java.util.Map;
import javax.sql.DataSource;

import org.springframework.http.CacheControl;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class HealthController {

    private final DataSource dataSource;

    public HealthController(DataSource dataSource) {
        this.dataSource = dataSource;
    }

    @GetMapping("/health")
    public ResponseEntity<Map<String, String>> health() {
        boolean ready = false;
        try (Connection connection = dataSource.getConnection()) {
            ready = connection.isValid(2);
        } catch (SQLException ignored) {
            // Readiness must not disclose database credentials or exception details.
        }
        return ResponseEntity.status(ready ? 200 : 503)
                .cacheControl(CacheControl.noStore())
                .body(Collections.singletonMap("status", ready ? "ok" : "unhealthy"));
    }
}

package com.photoalbum.controller;

import java.sql.Connection;
import java.sql.SQLException;
import java.util.Map;
import javax.sql.DataSource;

import org.junit.jupiter.api.Test;
import org.springframework.http.ResponseEntity;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

class HealthControllerTests {

    @Test
    void reportsDatabaseReadinessAndClosesConnection() throws SQLException {
        DataSource source = mock(DataSource.class);
        Connection connection = mock(Connection.class);
        when(source.getConnection()).thenReturn(connection);
        when(connection.isValid(2)).thenReturn(true);

        ResponseEntity<Map<String, String>> response = new HealthController(source).health();

        assertEquals(200, response.getStatusCode().value());
        assertEquals("ok", response.getBody().get("status"));
        assertEquals("no-store", response.getHeaders().getCacheControl());
        verify(connection).close();
    }

    @Test
    void invalidConnectionIsNotHealthy() throws SQLException {
        DataSource source = mock(DataSource.class);
        Connection connection = mock(Connection.class);
        when(source.getConnection()).thenReturn(connection);
        when(connection.isValid(2)).thenReturn(false);

        ResponseEntity<Map<String, String>> response = new HealthController(source).health();

        assertEquals(503, response.getStatusCode().value());
        assertEquals("unhealthy", response.getBody().get("status"));
        verify(connection).close();
    }

    @Test
    void databaseFailureDoesNotDiscloseConnectionDetails() throws SQLException {
        DataSource source = mock(DataSource.class);
        when(source.getConnection()).thenThrow(new SQLException("connection details must stay private"));

        ResponseEntity<Map<String, String>> response = new HealthController(source).health();

        assertEquals(503, response.getStatusCode().value());
        assertEquals(1, response.getBody().size());
        assertEquals("unhealthy", response.getBody().get("status"));
    }
}
